SET XACT_ABORT ON;
BEGIN TRANSACTION;
CREATE TABLE dbo.Site(SiteId int IDENTITY PRIMARY KEY,SiteCode nvarchar(30) NOT NULL UNIQUE,SiteName nvarchar(150) NOT NULL,SiteType varchar(30) NOT NULL,IsActive bit NOT NULL CONSTRAINT DF_Site_Active DEFAULT(1),CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT CK_Site_Type CHECK(SiteType IN('FACTORY','EXTERNAL_WAREHOUSE')));
CREATE TABLE dbo.Zone(ZoneId bigint IDENTITY PRIMARY KEY,SiteId int NOT NULL,ZoneCode nvarchar(40) NOT NULL,ZoneName nvarchar(150) NOT NULL,ZoneType varchar(30) NOT NULL,IsActive bit NOT NULL DEFAULT(1),CONSTRAINT FK_Zone_Site FOREIGN KEY(SiteId) REFERENCES dbo.Site(SiteId),CONSTRAINT UQ_Zone_Code UNIQUE(SiteId,ZoneCode));
CREATE TABLE dbo.Pallet(PalletId bigint IDENTITY PRIMARY KEY,PalletCode nvarchar(50) NOT NULL UNIQUE,PalletType nvarchar(40) NOT NULL,Status varchar(20) NOT NULL DEFAULT('ACTIVE'),CurrentZoneId bigint NULL,LastConfirmedAt datetime2(3) NULL,CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),RowVersion rowversion,CONSTRAINT FK_Pallet_Zone FOREIGN KEY(CurrentZoneId) REFERENCES dbo.Zone(ZoneId),CONSTRAINT CK_Pallet_Status CHECK(Status IN('ACTIVE','IN_TRANSIT','INACTIVE','EXCEPTION')));
CREATE TABLE dbo.PalletEpc(PalletEpcId bigint IDENTITY PRIMARY KEY,PalletId bigint NOT NULL,Epc nvarchar(128) NOT NULL,IsActive bit NOT NULL DEFAULT(1),AssignedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),DeactivatedAt datetime2(3) NULL,CONSTRAINT FK_PalletEpc_Pallet FOREIGN KEY(PalletId) REFERENCES dbo.Pallet(PalletId));
CREATE UNIQUE INDEX UX_PalletEpc_ActiveEpc ON dbo.PalletEpc(Epc) WHERE IsActive=1; CREATE UNIQUE INDEX UX_PalletEpc_ActivePallet ON dbo.PalletEpc(PalletId) WHERE IsActive=1;
CREATE TABLE dbo.PalletContent(PalletContentId bigint IDENTITY PRIMARY KEY,PalletId bigint NOT NULL,MaterialNumber nvarchar(80) NOT NULL,Quantity decimal(18,4) NOT NULL,Uom nvarchar(12) NOT NULL,IsActive bit NOT NULL DEFAULT(1),UpdatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_PalletContent_Pallet FOREIGN KEY(PalletId) REFERENCES dbo.Pallet(PalletId),CONSTRAINT CK_PalletContent_Qty CHECK(Quantity>0)); CREATE INDEX IX_PalletContent_Material ON dbo.PalletContent(MaterialNumber,IsActive);
CREATE TABLE dbo.RfidReader(ReaderId bigint IDENTITY PRIMARY KEY,ReaderCode nvarchar(50) NOT NULL UNIQUE,ZoneId bigint NOT NULL,ReaderVendor nvarchar(80) NULL,IsActive bit NOT NULL DEFAULT(1),LastHeartbeatAt datetime2(3) NULL,CONSTRAINT FK_RfidReader_Zone FOREIGN KEY(ZoneId) REFERENCES dbo.Zone(ZoneId));
CREATE TABLE dbo.RfidRawEvent(RawEventId bigint IDENTITY PRIMARY KEY,SourceEventKey nvarchar(160) NULL,Epc nvarchar(128) NOT NULL,ReaderId bigint NULL,AntennaNo int NULL,Rssi decimal(8,3) NULL,ObservedAt datetime2(3) NOT NULL,ReceivedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),ProcessingStatus varchar(20) NOT NULL DEFAULT('NEW'),CONSTRAINT FK_RawEvent_Reader FOREIGN KEY(ReaderId) REFERENCES dbo.RfidReader(ReaderId),CONSTRAINT CK_RawEvent_Status CHECK(ProcessingStatus IN('NEW','PROCESSED','IGNORED','EXCEPTION'))); CREATE UNIQUE INDEX UX_RawEvent_SourceKey ON dbo.RfidRawEvent(SourceEventKey) WHERE SourceEventKey IS NOT NULL; CREATE INDEX IX_RawEvent_Epc_Time ON dbo.RfidRawEvent(Epc,ObservedAt DESC);
CREATE TABLE dbo.PalletMovement(MovementId bigint IDENTITY PRIMARY KEY,MovementEventKey nvarchar(160) NOT NULL UNIQUE,PalletId bigint NOT NULL,FromZoneId bigint NULL,ToZoneId bigint NOT NULL,MovementType varchar(30) NOT NULL,DetectionMethod varchar(20) NOT NULL,ConfirmedAt datetime2(3) NOT NULL,ConfirmedBy nvarchar(80) NULL,CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_Move_Pallet FOREIGN KEY(PalletId) REFERENCES dbo.Pallet(PalletId),CONSTRAINT FK_Move_From FOREIGN KEY(FromZoneId) REFERENCES dbo.Zone(ZoneId),CONSTRAINT FK_Move_To FOREIGN KEY(ToZoneId) REFERENCES dbo.Zone(ZoneId),CONSTRAINT CK_Move_Method CHECK(DetectionMethod IN('RFID_GATE','HANDHELD_RFID','MANUAL'))); CREATE INDEX IX_Move_Pallet_Time ON dbo.PalletMovement(PalletId,ConfirmedAt DESC);
CREATE TABLE dbo.RfidException(ExceptionId bigint IDENTITY PRIMARY KEY,RawEventId bigint NULL,Epc nvarchar(128) NULL,ExceptionType varchar(40) NOT NULL,Description nvarchar(1000) NOT NULL,Status varchar(20) NOT NULL DEFAULT('OPEN'),CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),ResolvedAt datetime2(3) NULL,ResolvedBy nvarchar(80) NULL,CONSTRAINT FK_Exception_RawEvent FOREIGN KEY(RawEventId) REFERENCES dbo.RfidRawEvent(RawEventId),CONSTRAINT CK_Exception_Status CHECK(Status IN('OPEN','IN_PROGRESS','RESOLVED','CANCELLED')));
CREATE TABLE dbo.IntegrationOutbox(OutboxId bigint IDENTITY PRIMARY KEY,EventType nvarchar(80) NOT NULL,AggregateId bigint NOT NULL,Payload nvarchar(max) NOT NULL,Status varchar(20) NOT NULL DEFAULT('PENDING'),AttemptCount int NOT NULL DEFAULT(0),CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),ProcessedAt datetime2(3) NULL,CONSTRAINT CK_Outbox_Json CHECK(ISJSON(Payload)=1),CONSTRAINT CK_Outbox_Status CHECK(Status IN('PENDING','PROCESSING','SENT','FAILED'))); CREATE INDEX IX_Outbox_Status_Time ON dbo.IntegrationOutbox(Status,CreatedAt);
COMMIT TRANSACTION;
